import { test, expect } from '@playwright/test';

test('search shows results after debounce', async ({ page }) => {
  // Mock the search API so we control the response and the count.
  await page.route('**/api/search?q=playwright', (route) =>
    route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ count: 15, items: [] }),
    }),
  );

  // Take real time out of the equation.
  await page.clock.install();

  await page.goto('/search');
  await page.getByLabel('Search').fill('playwright');

  // Advance virtual time past the 300ms debounce.
  await page.clock.runFor(310);

  // Web-first assertion auto-retries until the count appears.
  await expect(page.getByText('15 results found')).toBeVisible();
});
